import { Flex, Image, Navbar, Text } from "@paraxe/react";
import type { Navbar01Props } from "../shared/types";
import "../shared/navbar.css";

export function Navbar01({ brandName = "Paraxe home", logoSrc = "/paraxe/navbar-01/mark.svg",
  shopHref = "/shop", collectionHref = "/collection", cartHref = "/cart",
  cartCount = 0, activeLink = "shop", shopLabel = "The shop", collectionLabel = "The collection", cartLabel = "Cart", editionLabel = "PARAXE", edition = "01" }: Navbar01Props) {
  return <Navbar className="navbar01"
    brand={<a className="navbar01-brand" href={shopHref} aria-label={brandName}><Image src={logoSrc} alt="" fit="contain" /></a>}
    actions={<Flex as="span" className="navbar01-edition" align="center" size="small"><Text as="span">{editionLabel}</Text><Text as="span" tone="muted">/ {edition}</Text></Flex>}>
    <nav className="navbar01-nav" aria-label="Shop navigation"><Flex align="center" justify="center" wrap>
      <a href={shopHref} aria-current={activeLink === "shop" ? "page" : undefined}>{shopLabel}</a>
      <a href={collectionHref} aria-current={activeLink === "collection" ? "page" : undefined}><Flex as="span" align="center" size="small">{collectionLabel}<span className="navbar01-arrow" aria-hidden="true">↗</span></Flex></a>
      <a href={cartHref} aria-current={activeLink === "cart" ? "page" : undefined}>{cartLabel} ({cartCount})</a>
    </Flex></nav>
  </Navbar>;
}

.navbar01.navbar {
  --navbar01-max-width: var(--container-max-width);
  --navbar01-gutter: var(--container-padding);
  --navbar01-height: calc(var(--nav-height) * 1.333333);
  --navbar01-top-rule: var(--space-2);
  --navbar01-side-width: calc(var(--space-4) * 9);
  --navbar01-link-gap: var(--space-9);
  --navbar01-logo-width: calc(var(--space-4) * 2.75);
  --navbar01-logo-height: calc(var(--space-4) * 3);
  position: relative;
  top: auto;
  z-index: auto;
  box-sizing: border-box;
  width: 100%;
  min-height: calc(var(--navbar01-height) + var(--navbar01-top-rule));
  gap: var(--inline-gap-lg);
  padding-inline: max(var(--navbar01-gutter), calc((100% - var(--navbar01-max-width)) / 2));
  border-block-start: var(--navbar01-top-rule) solid var(--text-primary);
  border-block-end: var(--border-width-thin) solid var(--border-default);
  backdrop-filter: none;
  font-family: var(--font-family-body);
}
.navbar01 *, .navbar01 *::before, .navbar01 *::after { box-sizing: border-box; }
.navbar01 .navbar-brand { flex: 0 0 var(--navbar01-side-width); }
.navbar01 .navbar-content { justify-content: center; }
.navbar01 .navbar-actions { flex: 0 0 var(--navbar01-side-width); justify-content: flex-end; margin-inline-start: 0; }
.navbar01-brand { display: block; width: calc(var(--space-4) * 3); padding-block: var(--space-2); }
.navbar01-brand .media { width: var(--navbar01-logo-width); height: var(--navbar01-logo-height); }
.navbar01-nav > .flex { gap: var(--navbar01-link-gap); }
.navbar01-nav a { display: inline-flex; align-items: center; min-height: calc(var(--space-4) * 2.75); padding-block: var(--space-3); border-block-end: var(--border-width-strong) solid transparent; color: inherit; font-size: var(--typography-nav-size); font-weight: var(--font-weight-regular); text-decoration: none; white-space: nowrap; }
.navbar01-nav a[aria-current="page"] { border-block-end-color: currentColor; }
.navbar01-nav a:hover { border-block-end-color: var(--border-strong); }
.navbar01-arrow { margin-inline-start: var(--space-3); font-size: var(--typography-micro-size); }
.navbar01-edition { white-space: nowrap; font-size: var(--typography-micro-size); letter-spacing: var(--letter-spacing-widest); font-weight: var(--font-weight-semibold); }
.navbar01 a:focus-visible { outline: var(--focus-ring-width) solid var(--focus-ring-color); outline-offset: var(--focus-ring-offset); }
@media (max-width: 48rem) {
  .navbar01.navbar { flex-wrap: wrap; gap: 0 var(--space-4); padding-block: var(--space-2); --navbar01-gutter: var(--space-4); }
  .navbar01 .navbar-brand { flex: 1 1 auto; }
  .navbar01 .navbar-actions { flex: 0 0 auto; }
  .navbar01 .navbar-content { order: 3; flex: 1 0 100%; }
  .navbar01-nav > .flex { gap: var(--inline-gap-lg); }
  .navbar01-nav a { font-size: var(--typography-micro-size); }
}

.navbar01 :is(.text-primary, .text-muted) { color: inherit; }

export interface Navbar01Props {
  brandName?: string;
  logoSrc?: string;
  shopHref?: string;
  collectionHref?: string;
  cartHref?: string;
  cartCount?: number;
  activeLink?: "shop" | "collection" | "cart" | null;
  shopLabel?: string;
  collectionLabel?: string;
  cartLabel?: string;
  editionLabel?: string;
  edition?: string;
}
